package com.rikkeibank.account.model; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity @Table(name="bank_accounts") public class BankAccount{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(nullable=false,unique=true,length=30) private String accountNumber;@Column(nullable=false,length=80) private String ownerUsername;@ManyToOne(optional=false,fetch=FetchType.EAGER) @JoinColumn(name="account_type_id") private AccountType accountType;@Column(nullable=false,precision=19,scale=2) private BigDecimal balance=BigDecimal.ZERO;@Column(nullable=false) private boolean active=true;@Version private Long version;@Column(nullable=false) private LocalDateTime createdAt=LocalDateTime.now();public Long getId(){return id;}public void setId(Long v){id=v;}public String getAccountNumber(){return accountNumber;}public void setAccountNumber(String v){accountNumber=v;}public String getOwnerUsername(){return ownerUsername;}public void setOwnerUsername(String v){ownerUsername=v;}public AccountType getAccountType(){return accountType;}public void setAccountType(AccountType v){accountType=v;}public BigDecimal getBalance(){return balance;}public void setBalance(BigDecimal v){balance=v;}public boolean isActive(){return active;}public void setActive(boolean v){active=v;}public Long getVersion(){return version;}public LocalDateTime getCreatedAt(){return createdAt;}public void setCreatedAt(LocalDateTime v){createdAt=v;}}
